syntax:
int total = 100;            // global: declared outside all functions

void counter() {
    int normal = 0;         // ordinary local: new on every call
    static int calls = 0;   // static local: created ONCE, keeps its value
    normal++;
    calls++;
}

int main() {
    int x = 5;              // local to main
    {
        int x = 50;         // block scope: hides the outer x inside { }
    }                       // inner x is destroyed here
    return 0;
}

sample.code:
#include <iostream>
using namespace std;

void counter() {
    int normal = 0;
    static int calls = 0;
    normal++;
    calls++;
    cout << "normal = " << normal << ", calls = " << calls << endl;
}

int main() {
    counter();
    counter();
    return 0;
}

#include <iostream>
using namespace std;

int total = 100;

void show() {
    cout << "show sees total = " << total << endl;
}

int main() {
    int x = 5;
    {
        int x = 50;
        cout << "inner x = " << x << endl;
    }
    cout << "outer x = " << x << endl;
    int total = 1;
    cout << "main total = " << total << endl;
    show();
    return 0;
}

#include <iostream>
using namespace std;

int nextToken() {
    static int last = 100;
    last = last + 1;
    return last;
}

int plainToken() {
    int last = 100;
    last = last + 1;
    return last;
}

int main() {
    int a = nextToken();
    int b = nextToken();
    int c = nextToken();
    int p = plainToken();
    int q = plainToken();
    cout << a << " " << b << " " << c << endl;
    cout << p << " " << q << endl;
    return 0;
}

